document.querySelectorAll('[data-lab="G17-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const z=root.dataset.language==='zh',kbox=root.querySelector('[data-k]'),dbox=root.querySelector('[data-d]'),tbox=root.querySelector('[data-temperature]'),pic=root.querySelector('[data-picture]'),out=root.querySelector('[data-result]');function update(){const k=Number(kbox.value),d=Number(dbox.value),t=Number(tbox.value),rt=.008314462618*t,u=.5*k*d*d,f=-k*d,sigma=Math.sqrt(rt/k);let p=[],left=[],right=[];const x=(q,offset)=>offset+380*(q+.25)/.5;for(let j=0;j<=200;j++){const q=-.25+j*.0025;left.push(x(q,85)+','+(385-285*(.5*k*q*q)/65));right.push(x(q,650)+','+(385-285*Math.exp(-.5*k*q*q/rt)));}p.push(`<text x="85" y="38" font-size="26">${z?'谐和偏置能量':'Harmonic bias energy'}</text><text x="650" y="38" font-size="26">${z?'局部平坦自由能参照':'Locally flat free-energy reference'}</text>`);for(const offset of [85,650]){p.push(`<path d="M${offset} 90 V385 H${offset+380}" stroke="#727f80" fill="none" stroke-width="2"/>`);for(const q of [-.2,0,.2])p.push(`<text x="${x(q,offset)}" y="415" text-anchor="middle" font-size="22">${q.toFixed(1)}</text>`);p.push(`<text x="${offset+190}" y="451" text-anchor="middle" font-size="22">${z?'偏离中心 / nm':'Displacement / nm'}</text>`);}p.push(`<polyline points="${left.join(' ')}" fill="none" stroke="#c56c3c" stroke-width="4"/><polyline points="${right.join(' ')}" fill="none" stroke="#147d92" stroke-width="4"/><circle cx="${x(d,85)}" cy="${385-285*u/65}" r="7" fill="#273b43"/><circle cx="${x(d,650)}" cy="${385-285*Math.exp(-u/rt)}" r="7" fill="#273b43"/>`);for(const val of [0,20,40,60])p.push(`<text x="72" y="${390-285*val/65}" text-anchor="end" font-size="20">${val}</text>`);for(const val of [0,.5,1])p.push(`<text x="635" y="${390-285*val}" text-anchor="end" font-size="20">${val.toFixed(1)}</text>`);p.push(`<text x="88" y="75" font-size="20">U / kJ mol⁻¹</text><text x="653" y="75" font-size="20">exp(−U / RT)</text><text x="35" y="488" font-size="19">${z?'右图以峰值归一化；参照标准差':'Right curve normalized by its peak; reference standard deviation'} σ = ${sigma.toFixed(5)} nm</text>`);pic.innerHTML=p.join('');root.querySelector('[data-readout]').textContent=d.toFixed(3)+' nm';out.textContent=z?`解析谐和模型：偏置能量 ${u.toFixed(3)} kJ/mol，恢复力 ${f.toFixed(2)} kJ mol⁻¹ nm⁻¹，热宽度参照 ${sigma.toFixed(5)} nm。恢复力的正方向为增大端距；温度 ${t} K。`:`Analytic harmonic model: bias energy ${u.toFixed(3)} kJ/mol, restoring force ${f.toFixed(2)} kJ mol⁻¹ nm⁻¹, and reference thermal width ${sigma.toFixed(5)} nm. Positive force increases end distance; temperature ${t} K.`;}kbox.addEventListener('change',update);dbox.addEventListener('input',update);tbox.addEventListener('change',update);root.querySelector('[data-reset]').addEventListener('click',()=>{kbox.value='1000';dbox.value='0.05';tbox.value='298';update();});update();});